// The one hand-written file in this package. Everything else (src/schema.d.ts) is
// generated by openapi-typescript from apps/api/openapi.json -- regenerate it with
// `pnpm contract:generate` from the repo root, never edit it directly. The pydantic
// models in apps/api/src/api are the real source of truth; this package only mirrors
// their shape for TypeScript clients.
export type { components, paths } from "./schema.d.ts";

import type { components } from "./schema.d.ts";

/** One named schema from `components.schemas` -- e.g. `Schema<"Health">` for apps/api's
 * `Health` response model (api.main). The shape every TS client imports instead of
 * hand-writing its own copy of an API request or response body. */
export type Schema<Name extends keyof components["schemas"]> =
  components["schemas"][Name];
